fn safe_divide(a: Int, b: Int) -> Option[Int] {
  if b == 0 { return None(); }
  return Some(a / b);
}

fn fuzz_divide() -> Int {
  // Simulate fuzzing by testing edge cases
  let test_cases = [
    (10, 2), (0, 5), (5, 0), (-10, 3), (Int.MAX, 1), (Int.MIN, -1),
    (100, 3), (-100, -3), (1, 1), (0, 1)
  ];
  var crashes = 0;
  for (a, b) in test_cases {
    match safe_divide(a, b) {
      Some(_) => {},
      None => { crashes = crashes + 1; },
    }
  }
  return crashes;
}

fn main() -> Int {
  return fuzz_divide();
}
